function Assert-ProCompoundRequest($Request,$Owner){
 if($Request.caseId -cne $Owner.caseId -or $Request.ownerPid -ne $Owner.pid -or $Owner.pid -lt 1 -or $Request.nonce -cne $Owner.nonce -or $Owner.nonce -cnotmatch '^[a-f0-9]{64}$' -or $Request.phase -cne 'run' -or $Request.action -cnotin @('hold-outage','release-pressure','restore-management')){throw 'Compound request owner/action changed'}
 $sequence=@{'hold-outage'=1;'release-pressure'=2;'restore-management'=3};if($Request.sequence -ne $sequence[$Request.action]){throw 'Compound action sequence changed'}
 foreach($value in @($Request.id,$Request.platformId,$Request.requestId)){$id=[guid]::Empty;if(-not [guid]::TryParseExact([string]$value,'D',[ref]$id) -or $id -eq [guid]::Empty -or $id.ToString('D') -cne $value){throw 'Canonical compound identities required'}}
 if(@($Request.psobject.Properties.Name|Where-Object{$_ -notin @('caseId','phase','ownerPid','nonce','requestId','action','sequence','id','platformId')}).Count){throw 'Unexpected compound request field'}
}
function Write-ProCompoundJson([string]$File,$Value){
 [IO.File]::WriteAllText($File+'.next',($Value|ConvertTo-Json -Depth 18),[Text.UTF8Encoding]::new($false));if(Test-Path -LiteralPath $File){[IO.File]::Replace($File+'.next',$File,[NullString]::Value)}else{[IO.File]::Move($File+'.next',$File)}
}
function Invoke-ProCompoundPhase($Session,[string]$Phase,$Guard,[string]$ProNonce,[long]$MaxFillBytes){
 $meta=$Guard.ReadCommand('compound-inputs.json')|ConvertFrom-Json;if($meta.format -ne 1 -or $meta.proNonce -ne $ProNonce -or $meta.caseId -notmatch '^[a-f0-9]{32}$' -or $meta.appCase -notmatch '^[a-f0-9]{32}$' -or $meta.supportCase -notmatch '^[a-f0-9]{32}$'){throw 'Bound compound fixture required'}
 if($Phase -eq 'compound-stage'){
  $Guard.PinInputFile([string]$meta.zip);if((Get-FileHash $meta.zip).Hash.ToLowerInvariant() -ne $meta.zipSha256){throw 'Compound payload changed'};$archive='C:\MuLab\private\compound-'+$meta.caseId+'.zip';Copy-Item -LiteralPath $meta.zip -Destination $archive -ToSession $Session
  return Invoke-Command -Session $Session -ArgumentList $meta,$archive -ScriptBlock {
   param($meta,$archive)
   $ErrorActionPreference='Stop';$tools='C:\MuLab\compound-tools\'+$meta.caseId;$file='C:\MuLab\approved\compound-'+$meta.caseId+'-config.json';if(@(Get-VM).Count -or (Get-Service vmms).Status -ne 'Running' -or (Test-Path $tools) -or (Test-Path $file)){throw 'Fresh idle Pro fixture required'}
   $app='C:\MuLab\volume-tools\'+$meta.appCase+'\app';foreach($entry in $meta.artifacts.psobject.Properties){if((Get-FileHash (Join-Path $app $entry.Name)).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Reused packaged compound program differs'}}
   $support=[IO.File]::ReadAllText(('C:\MuLab\approved\image-'+$meta.supportCase+'-config.json'))|ConvertFrom-Json;$node='C:\MuLab\image-tools\'+$meta.supportCase+'\product\resources\node\node.exe';if($support.image -ne ('C:\MuLab\images\image-'+$meta.supportCase+'.vhdx') -or (Get-FileHash $support.image).Hash.ToLowerInvariant() -ne $meta.imageSha256 -or (Get-FileHash $node).Hash.ToLowerInvariant() -ne $meta.nodeSha256 -or (Get-FileHash $archive).Hash.ToLowerInvariant() -ne $meta.zipSha256){throw 'Compound image/runtime/archive differs'}
   Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::OpenRead($archive);try{$allowed=@('pro-compound-client.mjs','local-fixtures.mjs','fixture-key.pem','fixture-cert.pem');if($zip.Entries.Count -ne 4 -or @($zip.Entries|Where-Object{$_.FullName -notin $allowed -or $_.Length -gt 2MB}).Count){throw 'Unexpected compound archive'}}finally{$zip.Dispose()};[IO.Compression.ZipFile]::ExtractToDirectory($archive,$tools);foreach($entry in $meta.files.psobject.Properties){if((Get-FileHash (Join-Path $tools $entry.Name)).Hash.ToLowerInvariant() -ne $entry.Value){throw 'Compound staged file differs'}}
   $config=@{caseId=$meta.caseId;version=$meta.version;proNonce=$meta.proNonce;tools=$tools;app=$app;node=$node;nodeSha256=$meta.nodeSha256;image=$support.image;imageSha256=$meta.imageSha256;sourceDigest=$meta.sourceDigest;artifacts=$meta.artifacts;clientSha256=$meta.files.'pro-compound-client.mjs';userSid=(Get-LocalUser MuLabUser).SID.Value};[IO.File]::WriteAllText($file,($config|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));return @{complete=$true;caseId=$meta.caseId;staged=$true;serviceChanged=$false}
  }
 }
 $policy=(Get-Command Assert-ProCompoundRequest).ScriptBlock.ToString();$writer=(Get-Command Write-ProCompoundJson).ScriptBlock.ToString()
 return Invoke-Command -Session $Session -ArgumentList $meta.caseId,$Phase,$policy,$writer,$MaxFillBytes -ScriptBlock {
  param($caseId,$phase,$policy,$writer,$maxFillBytes)
  $ErrorActionPreference='Stop';$prefix='C:\MuLab\public\compound-'+$caseId;$approved='C:\MuLab\approved\compound-'+$caseId;$cfg=[IO.File]::ReadAllText($approved+'-config.json')|ConvertFrom-Json;$checkRequest=[ScriptBlock]::Create($policy);$write=[ScriptBlock]::Create($writer);$pressure='C:\MuLab\private\compound-'+$caseId+'-pressure.bin'
  if($cfg.caseId -ne $caseId -or $cfg.tools -ne ('C:\MuLab\compound-tools\'+$caseId)){throw 'Compound config changed'}
  if($phase -eq 'compound-inspect'){
   $results=@();$progress=@();$logs=@();foreach($step in @('run','recover')){foreach($kind in @('result','progress')){$file=$prefix+'-'+$step+'-'+$kind+'.json';if(Test-Path $file){$value=[IO.File]::ReadAllText($file)|ConvertFrom-Json;if($kind -eq 'result'){$results+=$value}else{$progress+=$value}}};$file=$prefix+'-'+$step+'-client.log';if(Test-Path $file){$stream=[IO.File]::Open($file,[IO.FileMode]::Open,[IO.FileAccess]::Read,([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete));try{if($stream.Length -gt 8000){$stream.Position=$stream.Length-8000};$reader=[IO.StreamReader]::new($stream);$logs+=@{step=$step;tail=$reader.ReadToEnd()}}finally{$stream.Dispose()}}};$observation=$null;if(Test-Path ($approved+'-observed.json')){$observation=[IO.File]::ReadAllText($approved+'-observed.json')|ConvertFrom-Json};$nested=$null;if((Get-Service vmms).Status -eq 'Running'){$nested=@(Get-VM|ForEach-Object{@{id=[string]$_.Id;state=[string]$_.State}})};return @{complete=$true;caseId=$caseId;results=$results;progress=$progress;logs=$logs;observation=$observation;service=[string](Get-Service vmms).Status;pressurePresent=(Test-Path $pressure);actors=@(Get-CimInstance Win32_Process|Where-Object{($_.ExecutablePath -eq $cfg.node -and $_.CommandLine -like ('*'+$caseId+'*')) -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-*.exe'}|Select-Object ProcessId,ExecutablePath,CommandLine);nested=$nested}
  }
  if((Get-Service vmms).Status -ne 'Running' -or (Test-Path $pressure)){throw 'Prior service/pressure state must be inspected'}
  if($phase -eq 'compound-collect'){
   $finished=[IO.File]::ReadAllText($approved+'-recover-result.json')|ConvertFrom-Json;if(-not $finished.complete -or -not $finished.processExitConfirmed -or -not $finished.brokerExitConfirmed -or -not $finished.nested.removed -or @(Get-VM).Count){throw 'Compound recovery cleanup incomplete'}
   $root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$cfg.userSid);$primary=Join-Path $root 'vms.json';$ledger=[IO.File]::ReadAllText($primary)|ConvertFrom-Json;if($ledger.version -ne 2 -or $ledger.ownerSid -ne $cfg.userSid -or @($ledger.records.psobject.Properties).Count -or (Get-FileHash $primary).Hash -ne (Get-FileHash (Join-Path $root 'vms.backup.json')).Hash -or @(Get-ChildItem -LiteralPath (Join-Path $root 'vms') -Force).Count){throw 'Compound protected resources remain'};$run=[IO.File]::ReadAllText($approved+'-run-result.json')|ConvertFrom-Json;$trip=[IO.File]::ReadAllText((Join-Path $root 'resource-trip.json'))|ConvertFrom-Json;if($trip.session -ne $run.nested.resourceSession -or $trip.reason -ne 'disk' -or [long]$trip.freeDiskBytes -ge 2GB){throw 'Independent protected native resource trip does not bind this run'};$hashes=@{};foreach($entry in $cfg.artifacts.psobject.Properties){$hashes[$entry.Name]=(Get-FileHash (Join-Path $cfg.app $entry.Name)).Hash.ToLowerInvariant()};return @{complete=$true;caseId=$caseId;version=$cfg.version;vmmsRunning=$true;pressureReleased=$true;nestedGuests=0;registeredGuests=0;runtimeDirectories=0;registrationCopiesEqual=$true;resourceTrip=$trip;sourceDigest=$cfg.sourceDigest;artifactHashes=$hashes;clientSha256=(Get-FileHash (Join-Path $cfg.tools 'pro-compound-client.mjs')).Hash.ToLowerInvariant()}
  }
  $step=if($phase -eq 'compound-run'){'run'}elseif($phase -eq 'compound-recover'){'recover'}else{throw 'Unsupported compound phase'}
  if($step -eq 'run'){if(@(Get-VM).Count){throw 'Empty Pro required for new compound run'}}else{$prior=[IO.File]::ReadAllText($approved+'-run-result.json')|ConvertFrom-Json;if(-not $prior.complete -or -not $prior.processExitConfirmed -or -not $prior.brokerExitConfirmed -or -not $prior.nested.confirmedOff){throw 'Completed stopped compound run required'}}
  $task='MuPro-compound-'+$caseId+'-'+$step;$ownerFile=$prefix+'-'+$step+'-owner.json';$resultFile=$prefix+'-'+$step+'-result.json';if((Test-Path $ownerFile) -or (Test-Path $resultFile) -or (Get-ScheduledTask -TaskName $task -ErrorAction SilentlyContinue)){throw 'Existing compound phase must be inspected'}
  $script=Join-Path $cfg.tools 'pro-compound-client.mjs';if((Get-FileHash $script).Hash.ToLowerInvariant() -ne $cfg.clientSha256 -or (Get-FileHash $cfg.node).Hash.ToLowerInvariant() -ne $cfg.nodeSha256){throw 'Compound client/runtime changed'}
  $launch='$env:PSModulePath=Join-Path $PSHOME ''Modules''; & '''+$cfg.node+''' --no-warnings '''+$script+''' '+$caseId+' '+$step+' *> '''+$prefix+'-'+$step+'-client.log'';exit $LASTEXITCODE';$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($launch));$principal=New-ScheduledTaskPrincipal -UserId 'MU-PRO-LAB\MuLabUser' -LogonType Interactive -RunLevel Limited;$action=New-ScheduledTaskAction -Execute (Join-Path $env:SystemRoot 'System32/WindowsPowerShell/v1.0/powershell.exe') -Argument ('-NoProfile -NonInteractive -WindowStyle Hidden -EncodedCommand '+$encoded) -WorkingDirectory C:\MuLab\public;$settings=New-ScheduledTaskSettingsSet -ExecutionTimeLimit ([TimeSpan]::FromHours(1)) -MultipleInstances IgnoreNew;Register-ScheduledTask -TaskName $task -Action $action -Principal $principal -Settings $settings|Out-Null;Start-ScheduledTask -TaskName $task
  $until=[DateTime]::UtcNow.AddMinutes(3);while(-not(Test-Path $ownerFile)){if([DateTime]::UtcNow -gt $until){throw 'Compound owner not observed; preserve its task'};Start-Sleep -Milliseconds 200};$owner=[IO.File]::ReadAllText($ownerFile)|ConvertFrom-Json;$actor=Get-CimInstance Win32_Process -Filter ('ProcessId='+[int]$owner.pid);if($owner.caseId -ne $caseId -or $owner.phase -ne $step -or $owner.nonce -notmatch '^[a-f0-9]{64}$' -or $actor.ExecutablePath -ne $cfg.node -or $actor.CommandLine -notlike ('*'+$script+'*'+$caseId+'*'+$step+'*') -or (Invoke-CimMethod -InputObject $actor -MethodName GetOwnerSid).Sid -ne $cfg.userSid){throw 'Actual compound controller binding changed'}
  $handle=Get-Process -Id $owner.pid;$null=$handle.Handle;$bin=Join-Path $env:ProgramData 'MuCodeSandbox-HyperVBroker-v1/bin';$artifact=[IO.File]::ReadAllText((Join-Path $bin 'current.json'))|ConvertFrom-Json;$broker=Join-Path $bin $artifact.brokerFile;if($artifact.sourceDigest -ne $cfg.sourceDigest -or (Get-FileHash $broker).Hash.ToLowerInvariant() -ne $artifact.brokerSha256){throw 'Protected compound broker changed'};$agent=Start-Process -FilePath $broker -ArgumentList @('--owner',[string]$owner.pid,'--pipe',[string]$owner.nonce,'--detect-host') -WorkingDirectory $bin -WindowStyle Hidden -RedirectStandardOutput ($approved+'-'+$step+'-broker-out.log') -RedirectStandardError ($approved+'-'+$step+'-broker-error.log') -PassThru;$null=$agent.Handle
  Add-Type -TypeDefinition ('using System;using System.IO;using System.Text;using System.Runtime.InteropServices;'+[IO.File]::ReadAllText((Join-Path $cfg.app 'dist-server/native/windows/ResourceMetrics.cs')));$root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$cfg.userSid);$filler=$null;$ownsOutage=$false;$restored=$false;$worker=$null;$stoppedAt=$null;$originalId=$null;$platformId=$null;$sequence=0;$last='';$until=[DateTime]::UtcNow.AddMinutes(30)
  try{do{
   $file=$prefix+'-request.json';if($step -eq 'run' -and (Test-Path $file)){$request=[IO.File]::ReadAllText($file)|ConvertFrom-Json;& $checkRequest $request $owner;if($request.requestId -ne $last){
    if($request.action -eq 'hold-outage'){
     if($sequence -ne 0 -or $ownsOutage){throw 'Compound outage cannot be replayed'};$vms=@(Get-VM);$originalId=[string]$request.id;$platformId=[string]$request.platformId;$ledger=[IO.File]::ReadAllText((Join-Path $root 'vms.json'))|ConvertFrom-Json;$record=$ledger.records.$originalId;$expected=Join-Path $root ('vms/'+$originalId+'/disk.vhdx')
     if($vms.Count -ne 1 -or [string]$vms[0].Id -ne $platformId -or $vms[0].Name -ne ('mu-win-'+$originalId.Replace('-','')) -or $vms[0].Notes -ne ('MuCodeSandbox Windows preview '+$vms[0].Name) -or [string]$vms[0].State -ne 'Running' -or $ledger.ownerSid -ne $cfg.userSid -or @($ledger.records.psobject.Properties).Count -ne 1 -or $record.platformId -ne $platformId -or $record.ownerSid -ne $cfg.userSid){throw 'Only the exact registered running synthetic VM may enter a compound outage'};$drives=@(Get-VMHardDiskDrive -VM $vms[0]);if($drives.Count -ne 1 -or [IO.Path]::GetFullPath($drives[0].Path) -ne $expected){throw 'Compound original disk boundary changed'}
     $workers=@(Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'"|Where-Object{$_.CommandLine -like ('*'+$platformId+'*')});if($workers.Count -ne 1){throw 'Unique original worker required'};$worker=Get-Process -Id $workers[0].ProcessId;$null=$worker.Handle;$amount=[long]([MuResourceMetrics]::Read($root)).freeDisk-1536MB;if($amount -lt 4GB -or $maxFillBytes -lt 8GB -or $amount -gt $maxFillBytes){throw 'Compound pressure exceeds its physical-headroom bound'}
     $service=Get-Service vmms;if($service.Status -ne 'Running'){throw 'Unexpected pre-existing VMMS outage'};$ownsOutage=$true;$service.Stop();$service.WaitForStatus([ServiceProcess.ServiceControllerStatus]::Stopped,[TimeSpan]::FromSeconds(45));$stoppedAt=[DateTime]::UtcNow;$filler=[IO.File]::Open($pressure,[IO.FileMode]::CreateNew,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);$filler.SetLength($amount);$filler.Flush($true);if(([MuResourceMetrics]::Read($root)).freeDisk -ge 2GB -or $worker.HasExited){throw 'Actual simultaneous pressure and surviving worker not observed'};$sequence=1
    }elseif($request.action -eq 'release-pressure'){
     if($sequence -ne 1 -or -not $filler -or $request.id -ne $originalId -or $request.platformId -ne $platformId){throw 'Pressure release sequence changed'};$filler.Dispose();$filler=$null;[IO.File]::Delete($pressure);$sequence=2
    }elseif($request.action -eq 'restore-management'){
     if($originalId -and ($request.id -ne $originalId -or $request.platformId -ne $platformId)){throw 'Management restoration identity changed'};if($filler){$filler.Dispose();$filler=$null;[IO.File]::Delete($pressure)};if($ownsOutage){$service=Get-Service vmms;if($service.Status -ne 'Running'){$service.Start();$service.WaitForStatus([ServiceProcess.ServiceControllerStatus]::Running,[TimeSpan]::FromSeconds(45))}};$restored=$true;$sequence=3
    }
    $response=@{complete=$true;caseId=$caseId;nonce=$owner.nonce;ownerPid=$owner.pid;requestId=$request.requestId;action=$request.action;sequence=$sequence;service=[string](Get-Service vmms).Status;pressureHeld=[bool]$filler;workerPid=$(if($worker){$worker.Id}else{$null});workerAlive=$(if($worker){-not $worker.HasExited}else{$null});freeDiskBytes=([MuResourceMetrics]::Read($root)).freeDisk;time=[DateTime]::UtcNow.ToString('o')};& $write ($approved+'-response.json') $response;$last=$request.requestId
   }}
   if($ownsOutage -and -not $restored){if((Get-Service vmms).Status -ne 'Stopped'){throw 'Unexpected VMMS recovery; restore/release independently'};if(([DateTime]::UtcNow-$stoppedAt).TotalSeconds -gt 180){throw 'Bounded compound outage expired'};& $write ($approved+'-observed.json') @{nonce=$owner.nonce;ownerPid=$owner.pid;service='Stopped';workerPid=$worker.Id;workerAlive=(-not $worker.HasExited);pressureHeld=[bool]$filler;freeDiskBytes=([MuResourceMetrics]::Read($root)).freeDisk;time=[DateTime]::UtcNow.ToString('o')}}
   if(Test-Path $resultFile){if(-not $handle.WaitForExit(15000) -or -not $agent.WaitForExit(45000)){throw 'Compound owner or broker remains live'};$result=[IO.File]::ReadAllText($resultFile)|ConvertFrom-Json;if($result.caseId -ne $caseId -or $result.pid -ne $owner.pid -or $result.nonce -cne $owner.nonce){throw 'Compound terminal receipt changed'};if((Get-Service vmms).Status -ne 'Running' -or $filler -or (Test-Path $pressure)){throw 'Service/pressure restoration incomplete'};$result|Add-Member -NotePropertyName processExitConfirmed -NotePropertyValue $true;$result|Add-Member -NotePropertyName brokerExitConfirmed -NotePropertyValue $true;& $write ($approved+'-'+$step+'-result.json') $result;Unregister-ScheduledTask -TaskName $task -Confirm:$false;return $result}
   if($handle.HasExited){throw 'Compound owner exited without receipt; preserve its resources'};if([DateTime]::UtcNow -gt $until){throw 'Compound process remains unconfirmed; inspect it'};Start-Sleep -Milliseconds 100
  }while($true)}finally{if($filler){$filler.Dispose();[IO.File]::Delete($pressure)};if($ownsOutage){$service=Get-Service vmms;if($service.Status -ne 'Running'){$service.Start();$service.WaitForStatus([ServiceProcess.ServiceControllerStatus]::Running,[TimeSpan]::FromSeconds(45))}};if($worker){$worker.Dispose()}}
 }
